20	/** The canonical wallet scenario names. */
21	export type ScenarioName =
22	  | 'fresh-install'
23	  | 'passwordless-signup'
24	  | 'foreign-pds'
25	  | 'unreachable-pds'
26	  | 'one-identity'
27	  | 'multi-identity'
28	  | 'alert-active'
29	  | 'migration-in-flight'
30	  | 'agent-connected'
