32	  | 'device-key-unusable'
33	  | 'rekey-eligible'
34	  | 'rekey-mixed'
35	  | 'self-held-kit'
36	  | 'self-held-kit-escrow-host'
37	  | 'recover-escrow'
38	  | 'recover-sovereign'
39	  | 'recover-wrong-set'
40	  | 'recover-corrupt-share'
