49	/** Every scenario builder, keyed by name. */
50	export const scenarios: Record<ScenarioName, () => WalletState> = {
51	  'fresh-install': () => emptyWalletState(),
52	
53	  /**
54	   * A first launch pointed at a Custos running with `accounts.password_optional` on, so it
55	   * advertises `optionalPassword` and the create flow never asks for a password: the handle
56	   * step submits directly, and `PasswordScreen` is not part of the flow at all.
57	   *
58	   * Deliberately a separate scenario rather than a capability added to `emptyWalletState`.
59	   * The flag is off by default on the server, so the default fixture keeps matching a stock
60	   * deployment — and every other scenario (and the docs screenshots built from them) keeps
61	   * exercising the with-password path, which is still what most hosts do.
62	   */
63	  'passwordless-signup': () => {
64	    const state = emptyWalletState();
65	    state.pdsCapabilities = {
66	      ...state.pdsCapabilities,
67	      capabilities: [...state.pdsCapabilities.capabilities, 'optionalPassword'],
68	    };
69	    return state;
70	  },
71	
72	  /**
73	   * A first launch pointed at a spec-compliant, non-Custos PDS: it advertises no Custos
74	   * capabilities, so the create flow's gate closes at the config step and steers to import.
75	   * This is the majority of the ecosystem (the reference PDS, bsky.social, rsky-pds), and
76	   * the only scenario that reaches `CreateUnavailableScreen`.
77	   */
78	  'foreign-pds': () => {
79	    const state = emptyWalletState();
80	    // Reached, and it genuinely advertises nothing — the answer that closes the gate.
81	    state.pdsCapabilities = { version: null, reached: true, capabilities: [] };
82	    state.availableUserDomains = ['.foreign.pds.local'];
83	    return state;
84	  },
85	
86	  /**
87	   * A host the capability probe could not reach. Indistinguishable from `foreign-pds`
88	   * through the capability list alone — which is the point: the create-flow gate must
89	   * show a retryable error here rather than telling the user their server cannot create
90	   * identities, a claim it has no evidence for.
91	   */
92	  'unreachable-pds': () => {
93	    const state = emptyWalletState();
94	    state.pdsCapabilities = { version: null, reached: false, capabilities: [] };
95	    return state;
96	  },
