277	    const state = emptyWalletState();
278	    state.pdsUrl = DEFAULT_PDS_URL;
279	    upsertIdentity(
280	      state,
281	      seedIdentity({ handle: 'alice.harness.pds.local', recoveryKey: false })
282	    );
283	    return state;
