288	  'rekey-mixed': () => {
289	    const state = emptyWalletState();
290	    state.pdsUrl = DEFAULT_PDS_URL;
291	    upsertIdentity(
292	      state,
293	      seedIdentity({ handle: 'oldmodel.harness.pds.local', recoveryKey: false })
294	    );
295	    upsertIdentity(
296	      state,
297	      seedIdentity({ handle: 'newmodel.harness.pds.local', recoveryKey: true })
