354	/** Whether a string names a known scenario. */
355	export function isScenarioName(name: string): name is ScenarioName {
356	  return name in scenarios;
357	}
358	
359	/** Build a state for `name`, falling back to the default for an unknown name. */
360	export function buildScenario(name: string): WalletState {
361	  return isScenarioName(name) ? scenarios[name]() : scenarios[DEFAULT_SCENARIO]();
362	}
