364	/**
365	 * An ISO timestamp `hours` before now — measured against the *live* clock, deliberately.
366	 *
367	 * The recovery-window UI reads these fixtures against `Date.now()` (`$lib/deadline`'s
368	 * `getUrgency`/`formatCountdown`, via `$lib/identity-status`), so a fixed base instant is
369	 * not a fixed *age*: it ages out. Pinned to a literal date, `isoHoursAgo(2)` stops being a
370	 * two-hour-old alert the moment real time passes it, and once 72 hours have elapsed the
371	 * `alert-active` scenario renders "Recovery window closed" — the one preset that exists to
372	 * demonstrate a live alarm no longer demonstrating one.
373	 *
374	 * Determinism for the docs screenshots is owned by the capture driver, not by a constant
375	 * here: `tools/screenshots/capture.mjs` freezes the page clock to `FIXED_CLOCK` before the
376	 * harness installs, so `Date.now()` there is that instant and every seeded age resolves
377	 * identically on every run.
378	 */
379	function isoHoursAgo(hours: number): string {
380	  return new Date(Date.now() - hours * 3600_000).toISOString();
381	}
