1	export const RECOVERY_WINDOW_MS = 72 * 60 * 60 * 1000; // 72 hours
2	
3	export function getDeadline(createdAt: string): Date {
4	  const timestamp = new Date(createdAt).getTime();
5	  if (isNaN(timestamp)) {
6	    throw new Error(`Invalid createdAt timestamp: ${createdAt}`);
7	  }
8	  return new Date(timestamp + RECOVERY_WINDOW_MS);
9	}
10	
11	export type Urgency = 'safe' | 'warning' | 'critical' | 'expired';
12	
13	export function getUrgency(deadline: Date, now: number = Date.now()): Urgency {
14	  const remaining = deadline.getTime() - now;
15	  if (remaining <= 0) return 'expired';
16	  if (remaining < 4 * 60 * 60 * 1000) return 'critical';
17	  if (remaining < 24 * 60 * 60 * 1000) return 'warning';
18	  return 'safe';
19	}
20	
21	export function formatCountdown(deadline: Date, now: number = Date.now()): string {
22	  const remaining = deadline.getTime() - now;
23	  if (remaining <= 0) return 'Expired';
24	  const hours = Math.floor(remaining / (1000 * 60 * 60));
25	  const minutes = Math.floor((remaining % (1000 * 60 * 60)) / (1000 * 60));
26	  return `${hours}h ${minutes}m remaining`;
27	}
